def parse_input_keyval(keyeqval):
    try:
        first_eq_pos = get_first_pos_of_char('=', keyeqval)
        if first_eq_pos == -1:
            raise
        if first_eq_pos > 0:
            name = keyeqval[:first_eq_pos]
